from pathlib import Path
path = Path('src/edgeiq-os/home/EdgeiqOsHome.tsx')
text = path.read_text(encoding='utf-8')
text = text.replace('''import { buildMissionControlModel } from "../services/mission-control";\nimport { loadMeetingsWorkspaceViewModel, type MeetingsWorkspaceViewModel } from "../race/services/meetingsFeed";\n''', '''import { buildMissionControlModel } from "../services/mission-control";\nimport { loadEdgeiqDailyPipelineStatus, type EdgeiqDailyPipelineStatus } from "../services/daily-pipeline/DailyPipelineStatusService";\nimport { loadMeetingsWorkspaceViewModel, type MeetingsWorkspaceViewModel } from "../race/services/meetingsFeed";\n''')
text = text.replace('''  const [model, setModel] = useState<MeetingsWorkspaceViewModel | null>(null);\n  const [loadError, setLoadError] = useState<string | null>(null);\n''', '''  const [model, setModel] = useState<MeetingsWorkspaceViewModel | null>(null);\n  const [pipelineStatus, setPipelineStatus] = useState<EdgeiqDailyPipelineStatus | null>(null);\n  const [loadError, setLoadError] = useState<string | null>(null);\n''')
text = text.replace('''  useEffect(() => {\n    let cancelled = false;\n    loadMeetingsWorkspaceViewModel()\n      .then((loaded) => {\n        if (!cancelled) {\n          setModel(loaded);\n          setLoadError(null);\n        }\n      })\n      .catch((error) => {\n        if (!cancelled) {\n          setModel(null);\n          setLoadError(error instanceof Error ? error.message : "Meeting workspace feed unavailable");\n        }\n      });\n    return () => {\n      cancelled = true;\n    };\n  }, []);\n''', '''  useEffect(() => {\n    let cancelled = false;\n    Promise.all([loadMeetingsWorkspaceViewModel(), loadEdgeiqDailyPipelineStatus()])\n      .then(([loaded, status]) => {\n        if (!cancelled) {\n          setModel(loaded);\n          setPipelineStatus(status);\n          setLoadError(null);\n        }\n      })\n      .catch((error) => {\n        if (!cancelled) {\n          console.warn("EDGEiQ home governed feed unavailable", error);\n          setModel(null);\n          setPipelineStatus(null);\n          setLoadError("Meeting feed unavailable");\n        }\n      });\n    return () => {\n      cancelled = true;\n    };\n  }, []);\n''')
text = text.replace('''  const allSystems = loadError ? "Attention Required" : "All Systems Operational";\n''', '''  const pipelineLabel = pipelineStatus?.status === "READY" ? "Ready" : pipelineStatus?.status === "WARN" ? "Review" : pipelineStatus?.status === "FAIL" ? "Unavailable" : "Pending";\n  const allSystems = loadError ? "Feed unavailable" : pipelineLabel;\n  const statusGeneratedAt = clean(pipelineStatus?.generated_at) || "Unavailable";\n''')
text = text.replace('''        {loadError ? <p className="eiq-home-approved__empty">{loadError}</p> : null}\n''', '''        {loadError ? (\n          <div className="eiq-home-approved__empty">\n            <strong>Meeting feed unavailable</strong>\n            <span>affected section: Today's Meetings</span>\n            <button className="eiq-approved-button" type="button" onClick={() => window.location.reload()}>Retry</button>\n          </div>\n        ) : null}\n''')
text = text.replace('''                <th>FIRST</th>\n                <th>LAST</th>\n                <th>STATUS</th>\n''', '')
text = text.replace('''                  <td>{display(meeting.weather)}</td>\n                  <td>{meeting.races}</td>\n                  <td>{meeting.declared}</td>\n                  <td>{meeting.scratchings}</td>\n                  <td>{display(meeting.first)}</td>\n                  <td>{display(meeting.last)}</td>\n                  <td><span className="eiq-approved-pill">Current</span></td>\n''', '''                  <td>{display(meeting.weather)}</td>\n                  <td>{meeting.races}</td>\n                  <td>{meeting.declared}</td>\n                  <td>{meeting.scratchings}</td>\n''')
text = text.replace('''                <tr><td colSpan={11}>Today's meeting feed is not available.</td></tr>\n''', '''                <tr><td colSpan={8}>Today's meeting feed is not available.</td></tr>\n''')
text = text.replace('''            <div><dt>Data Discipline</dt><dd>Browser-safe product feeds</dd></div>\n            <div><dt>Data Discipline</dt><dd>Browser-safe product feeds</dd></div>\n            <div><dt>Data Discipline</dt><dd>Browser-safe product feeds</dd></div>\n            <div><dt>Live Data Feeds</dt><dd>{allSystems}</dd></div>\n            <div><dt>Race Fields</dt><dd>{totalDeclared ? "Current" : "Pending"}</dd></div>\n            <div><dt>Reports & Results</dt><dd>Up to date</dd></div>\n            <div><dt>Weather Feeds</dt><dd>{mission.weatherWatch.label || "Governed unavailable"}</dd></div>\n''', '''            <div><dt>Pipeline</dt><dd>{allSystems}</dd></div>\n            <div><dt>Window</dt><dd>{pipelineStatus?.melbourne_date ?? currentDisplayDate(model)}</dd></div>\n            <div><dt>Meetings</dt><dd>{today?.totals.meetings ?? 0}</dd></div>\n            <div><dt>Races</dt><dd>{totalRaces}</dd></div>\n            <div><dt>Declared</dt><dd>{totalDeclared}</dd></div>\n            <div><dt>Scratchings</dt><dd>{totalScratchings}</dd></div>\n            <div><dt>Last Build</dt><dd>{statusGeneratedAt}</dd></div>\n''')
path.write_text(text, encoding='utf-8')
print('EDGEIQ_HOME_GOVERNED_DATA_COPY_REPAIRED')
